namespace Kuitit.Api.Files;

/// <summary>Blob storage addressed by an opaque key. Keys are generated by the app, never user input.</summary>
public interface IFileStore
{
    Task SaveAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Returns null when the key doesn't exist.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);

    /// <summary>No-op when the key doesn't exist.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}
